namespace Ims.Domain;

/// <summary>
/// Metadata of a file stored on disk (photos of delivery notes, product images, scanned documents). The bytes never live in the
/// database; <see cref="StoragePath"/> is relative to the configured storage root and generated by the system.
/// </summary>
public class Attachment : PublicEntity
{
    private Attachment() { }

    public AttachmentOwnerType OwnerType { get; private set; }
    public int OwnerId { get; private set; }
    /// <summary>Name shown to users and used for downloads (sanitised, extension from the detected kind).</summary>
    public string FileName { get; private set; } = "";
    public string StoragePath { get; private set; } = "";
    public string ContentType { get; private set; } = "";
    public FileKind Kind { get; private set; }
    public long SizeBytes { get; private set; }
    public string Sha256 { get; private set; } = "";
    public int UploadedBy { get; private set; }
    public DateTime UploadedAt { get; private set; }

    public static Attachment Create(AttachmentOwnerType ownerType, int ownerId, string clientFileName, FileKind kind, string storagePath,
        long sizeBytes, string sha256, int uploadedBy, DateTime now)
    {
        if (ownerId <= 0) throw new DomainException(Messages.AttachmentNotFound);
        if (sizeBytes <= 0) throw new DomainException(Messages.FileEmpty);
        if (sizeBytes > Limits.MaxAttachmentBytes) throw new DomainException(Messages.FileTooLarge(Limits.MaxAttachmentBytes));

        return new Attachment
        {
            OwnerType = ownerType, OwnerId = ownerId, FileName = AttachmentRules.SafeDisplayName(clientFileName, kind),
            StoragePath = storagePath, ContentType = AttachmentRules.ContentTypeOf(kind), Kind = kind,
            SizeBytes = sizeBytes, Sha256 = sha256, UploadedBy = uploadedBy, UploadedAt = now
        };
    }

    /// <summary>Soft delete (REC_DELETED): the row stays for the audit trail; the stored file is removed by the application afterwards.</summary>
    public void Delete() => MarkDeleted();
}
